class SelectivePolicy:
    """Fairness-aware selective deferral with group threshold optimization.

    Uses a learned correctness predictor, then searches over group-specific thresholds
    to minimize a weighted combination of selective risk, deferral gap, and coverage deviation.
    """

    def __init__(self, target_coverage: float = TARGET_COVERAGE_DEFAULT, random_state: int = 0):
        self.target_coverage = float(target_coverage)
        self.random_state = int(random_state)
        self.threshold_: float = 0.5
        self.group_thresholds_: dict[int, float] = {}
        self.meta_model_ = None
        self.strategy_name = "fairness_aware_group_opt"
        # Hyperparameters
        self.alpha = 2.0   # weight for deferral gap penalty
        self.beta = 20.0   # weight for coverage deviation penalty

    def fit(self, probs: np.ndarray, y_true: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> "SelectivePolicy":
        # Train meta-model to predict correctness
        features = _confidence_features(probs, groups, X)
        correct = (np.argmax(probs, axis=1) == y_true).astype(int)
        self.meta_model_ = Pipeline(
            steps=[
                ("scale", StandardScaler()),
                (
                    "clf",
                    LogisticRegression(
                        max_iter=1000,
                        solver="lbfgs",
                        class_weight="balanced",
                        random_state=self.random_state,
                    ),
                ),
            ]
        )
        self.meta_model_.fit(features, correct)
        scores = self.meta_model_.predict_proba(features)[:, 1]

        unique_groups = np.unique(groups)
        group_masks = {g: groups == g for g in unique_groups}
        group_scores = {g: scores[group_masks[g]] for g in unique_groups}
        group_correct = {g: correct[group_masks[g]] for g in unique_groups}
        group_sizes = {g: group_masks[g].sum() for g in unique_groups}
        total_examples = len(scores)

        # Discretize percentiles for each group (0% to 100% in steps of 5%)
        percentiles = np.linspace(0.0, 100.0, 21)  # 0,5,...,100
        # Precompute thresholds for each group at these percentiles
        group_thresholds_at_percentile = {}
        for g in unique_groups:
            if len(group_scores[g]) == 0:
                group_thresholds_at_percentile[g] = np.array([0.0] * len(percentiles))
            else:
                group_thresholds_at_percentile[g] = np.percentile(group_scores[g], percentiles)

        # Search over global percentile p and per-group offsets
        best_obj = float('inf')
        best_thresholds = {}
        for p in np.linspace(0.0, 100.0, 21):  # global percentile
            base_percentile = p
            # Offsets per group limited to +/-20 percentile points
            offsets_range = np.linspace(-20.0, 20.0, 9)  # -20,-15,...,20
            # Generate all combinations of offsets for groups (cartesian product)
            # Since number of groups is small (<=4), we can iterate
            from itertools import product
            for offsets in product(offsets_range, repeat=len(unique_groups)):
                thresholds = {}
                for idx, g in enumerate(unique_groups):
                    adjusted_percentile = np.clip(base_percentile + offsets[idx], 0.0, 100.0)
                    # Map percentile to threshold using precomputed array
                    # Find index of closest percentile
                    idx_closest = np.argmin(np.abs(percentiles - adjusted_percentile))
                    thresholds[g] = group_thresholds_at_percentile[g][idx_closest]
                # Compute metrics
                total_accepted = 0
                total_correct_accepted = 0
                group_deferral_rates = []
                for g in unique_groups:
                    mask = group_masks[g]
                    g_scores = scores[mask]
                    accept = g_scores >= thresholds[g]
                    total_accepted += accept.sum()
                    total_correct_accepted += np.sum(group_correct[g][accept])
                    group_deferral_rates.append(1.0 - accept.mean())
                coverage = total_accepted / total_examples if total_examples > 0 else 0.0
                if total_accepted > 0:
                    error = 1.0 - total_correct_accepted / total_accepted
                else:
                    error = 1.0
                deferral_gap = max(group_deferral_rates) - min(group_deferral_rates)
                obj = error + self.alpha * deferral_gap + self.beta * (coverage - self.target_coverage) ** 2
                if obj < best_obj:
                    best_obj = obj
                    best_thresholds = thresholds

        # Store thresholds
        self.group_thresholds_ = {int(g): float(best_thresholds[g]) for g in unique_groups}
        # Global threshold as median of group thresholds
        self.threshold_ = float(np.median(list(best_thresholds.values())))
        return self

    def acceptance_score(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        if self.meta_model_ is None:
            return np.max(probs, axis=1)
        features = _confidence_features(probs, groups, X)
        return self.meta_model_.predict_proba(features)[:, 1]

    def predict_accept(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        scores = self.acceptance_score(probs, groups, X)
        if self.group_thresholds_:
            thresholds = np.asarray([self.group_thresholds_.get(int(group), self.threshold_) for group in groups], dtype=float)
        else:
            thresholds = self.threshold_
        return scores >= thresholds

    def calibration_summary(self) -> dict[str, float]:
        summary = {"threshold": float(self.threshold_)}
        for group_id, threshold in self.group_thresholds_.items():
            summary[f"threshold_group_{group_id}"] = float(threshold)
        return summary
